#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>

int main() {
    std::mutex m;
    std::condition_variable cv;
    bool ready=false;
    std::thread worker([&]{{std::lock_guard lock(m);ready=true;}cv.notify_one();});
    {std::unique_lock lock(m);cv.wait(lock,[&]{return ready;});}
    worker.join();
    std::cout << "Ready";
}

